export function getSKMLAProfile(acNo: number): MLAProfile | undefined {
  return SK_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getSKMLAsByParty(party: string): MLAProfile[] {
  return SK_MLA_PROFILES.filter(p => p.party === party);
}

export function getSKFemaleMLAs(): MLAProfile[] {
  return SK_MLA_PROFILES.filter(p => p.gender === 'F');
}
